// Highlighting for code blocks
import "prismjs/themes/prism.css";

export const shouldUpdateScroll = ({ routerProps: { location } }) => {
  if (location.hash) {
    return decodeURI(location.hash.slice(1));
  }

  // A client-side navigation should behave like loading a new document. Keep
  // Gatsby's saved-position behavior only for browser back/forward navigation.
  return location.action === "POP" ? true : [0, 0];
};
